    ["<laughs>"] = "<сміється>",
    ["<laughs> And knowing you, you'll find it all."] = "<сміється> А знаючи тебе — ти все це знайдеш.",
    ["<pained groan>"] = "<стогін від болю>",
    ["<pained grunt>"] = "<стогін болю>",
