    ["<painful groaning>"] = "<болісний стогін>",
    ["<playful, evil laughter> <painful grunts>"] = "<грайливий, лиховісний сміх> <болісні стогони>",
    ["<roars in rage, swings his sword with fervor multiple times>"] = "<реве від люті, кілька разів несамовито змахує мечем>",
    ["<scoffs defensively>"] = "<захищаючись, пирхає>",
    ["<screaming angrily>"] = "<розлючено кричить>",
