    ["|TINTERFACE\\ICONS\\ABILITY_MONK_EXPLODINGJADEBLOSSOM.BLP:20|t Thorm'belan begins to cast |cFFFF0404|Hspell:1257825|h[Scintillating Shard]|h|r!"] = "|TINTERFACE\\ICONS\\ABILITY_MONK_EXPLODINGJADEBLOSSOM.BLP:20|t Торм'белан починає творити |cFFFF0404|Hspell:1257825|h[Іскристий уламок]|h|r!",
    ["|TINTERFACE\\ICONS\\Item_HolySpark.blp:20|t Thorm'belan begins to cast |cFFFF0404|Hspell:1257325|h[Radiant Mote]|h|r!"] = "|TINTERFACE\\ICONS\\Item_HolySpark.blp:20|t Торм'белан починає творити |cFFFF0404|Hspell:1257325|h[Променистий пилок]|h|r!",
    ["|TINTERFACE\\ICONS\\SPELL_NATURE_THORNS.BLP:20|t Thorm'belan begins to cast |cFFFF0404|Hspell:1258641|h[Shredding Tendrils]|h|r!"] = "|TINTERFACE\\ICONS\\SPELL_NATURE_THORNS.BLP:20|t Торм'белан починає творити |cFFFF0404|Hspell:1258641|h[Шматувальні щупальця]|h|r!",
    ["|TINTERFACE\\ICONS\\SPELL_NATURE_THORNS.BLP:20|t Thorm'belan casts |cFFFF0404|Hspell:1258641|h[Shredding Tendrils]|h|r on you!"] = "|TINTERFACE\\ICONS\\SPELL_NATURE_THORNS.BLP:20|t Торм'белан застосовує до тебе |cFFFF0404|Hspell:1258641|h[Пагони-Шматувальники]|h|r!",
    ["|TInterface\\ICONS\\Ability_DragonRiding_DragonRiding01.BLP:20|t Take flight!"] = "|TInterface\\ICONS\\Ability_DragonRiding_DragonRiding01.BLP:20|t Злітай!",
    ["|TInterface\\ICONS\\Ability_Kick.blp:20|t |cFFFF0404|Hspell:1218468|h[Bounce]|h|r rowdy patrons towards the exit!"] = "|TInterface\\ICONS\\Ability_Kick.blp:20|t |cFFFF0404|Hspell:1218468|h[Виштовхуй]|h|r буйних відвідувачів до виходу!",
    ["|TInterface\\ICONS\\Ability_Priest_Archangel.blp:20|t %s begins casting |cFFFF0000|Hspell:1258427|h[Radiant Flare]|h|r!"] = "|TInterface\\ICONS\\Ability_Priest_Archangel.blp:20|t %s починає творити |cFFFF0000|Hspell:1258427|h[Променистий спалах]|h|r!",
    ["|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s is preparing to |cFFFF0000|Hspell:267702|h[Entomb]|h|r |cFFFF0000{NAME}|r!"] = "|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s готується накласти |cFFFF0000|Hspell:267702|h[Поховання]|h|r на |cFFFF0000{NAME}|r!",
    ["|TInterface\\ICONS\\INV12_Ability_Priest_Madness_Scream.BLP:20|t %s begins to cast |cFFFF0000|Hspell:1292272|h[Cosmic Horror]|h|r. Look away!"] = "|TInterface\\ICONS\\INV12_Ability_Priest_Madness_Scream.BLP:20|t %s починає творити |cFFFF0000|Hspell:1292272|h[Космічний Жах]|h|r. Відверни погляд!",
    ["|TInterface\\ICONS\\INV_Ability_HolyFire_GroundState.BLP:20|t  You have been afflicted with |cFFFF0000|Hspell:1276427|h[Dawncrazed Halo]|h|r!"] = "|TInterface\\ICONS\\INV_Ability_HolyFire_GroundState.BLP:20|t  Тебе вразило |cFFFF0000|Hspell:1276427|h[Світанкошалений німб]|h|r!",
    ["|TInterface\\ICONS\\INV_CosmicVoid_Buff.blp:20|t  Draw in Void to heal your shield, and cast  |TInterface\\ICONS\\INV_CosmicVoid_Missile.blp:20|t  Void Spears at Antenorian!"] = "|TInterface\\ICONS\\INV_CosmicVoid_Buff.blp:20|t  Вбирай Порожнечу, щоб зцілити свій щит, і кидай  |TInterface\\ICONS\\INV_CosmicVoid_Missile.blp:20|t  Списи Порожнечі в Антеноріана!",
    ["|TInterface\\ICONS\\INV_Fyrakk_DragonBreath.BLP:20|t Fyrakk begins to unleash his |cFFFF0000|Hspell:410223|h[Shadowflame Breath]|h|r!"] = "|TInterface\\ICONS\\INV_Fyrakk_DragonBreath.BLP:20|t Фіракк починає вивільняти свій |cFFFF0000|Hspell:410223|h[Подих тіньового полум'я]|h|r!",
    ["|TInterface\\ICONS\\INV_KaijuGladiatorMount_Purple.blp:20|t You are being targeted by |cFFFF0000|Hspell:1227420|h[Hungering Presence]|h|r! Fly back!"] = "|TInterface\\ICONS\\INV_KaijuGladiatorMount_Purple.blp:20|t Тебе взято на приціл — |cFFFF0000|Hspell:1227420|h[Голодна Присутність]|h|r! Відлітай!",
    ["|TInterface\\ICONS\\INV_KaijuGladiatorMount_Purple.blp:20|t You are being targeted by |cFFFF0000|Hspell:1227420|h[Hungering Presence]|h|r! Return to lower ground!"] = "|TInterface\\ICONS\\INV_KaijuGladiatorMount_Purple.blp:20|t На тебе спрямовано |cFFFF0000|Hspell:1227420|h[Голодну Присутність]|h|r! Повернися на нижчий рівень!",
    ["|TInterface\\ICONS\\INV_Misc_Clipboard01.BLP:20|t |cFFFF0404|Hspell:1218465|h[Serve]|h|r patrons food & drink from the bar!"] = "|TInterface\\ICONS\\INV_Misc_Clipboard01.BLP:20|t |cFFFF0404|Hspell:1218465|h[Подавай]|h|r відвідувачам їжу та напої з бару!",
    ["|TInterface\\ICONS\\INV_Misc_DiscoBall_01.blp:20|t |cFFFF0404|Hspell:1218467|h[Entertain]|h|r on the stage!"] = "|TInterface\\ICONS\\INV_Misc_DiscoBall_01.blp:20|t |cFFFF0404|Hspell:1218467|h[Розважай]|h|r на сцені!",
    ["|TInterface\\ICONS\\INV_Misc_NotePicture1c.BLP:20|t %s targets you with a |cFFFF0404|Hspell:1257877|h[Scathing Review]|h|r!"] = "|TInterface\\ICONS\\INV_Misc_NotePicture1c.BLP:20|t %s націлює на тебе |cFFFF0404|Hspell:1257877|h[Нищівну рецензію]|h|r!",
    ["|TInterface\\ICONS\\INV_Pet_Broom.blp:20|t |cFFFF0404|Hspell:1218466|h[Clean]|h|r with the Enchanted Broom!"] = "|TInterface\\ICONS\\INV_Pet_Broom.blp:20|t |cFFFF0404|Hspell:1218466|h[Прибирай]|h|r Зачарованою мітлою!",
    ["|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t You have been trapped in a tomb! |cFFFF0000|Hspell:267764|h[Struggle]|h|r to let your friends know where you are!"] = "|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t Тебе замкнено в гробниці! |cFFFF0000|Hspell:267764|h[Борсайся]|h|r, щоб друзі знали, де ти!",
    ["|TInterface\\ICONS\\INV_ShadeBeastMount_Blue.BLP:20|t Denizens of the Beastwarrens fill your mind with |cFFFF0000|Hspell:336972|h[Otherworldly Screeching]|h|r!"] = "|TInterface\\ICONS\\INV_ShadeBeastMount_Blue.BLP:20|t Мешканці Звіриних Нір наповнюють твій розум |cFFFF0000|Hspell:336972|h[Потойбічним Вереском]|h|r!",
    ["|TInterface\\ICONS\\INV_Shield_DeathwingRaid_D_02.blp:20|t Fyrakk begins to |cFFFF0000|Hspell:419144|h[Corrupt]|h|r the Heart of Amirdrassil!"] = "|TInterface\\ICONS\\INV_Shield_DeathwingRaid_D_02.blp:20|t Фаєрак починає |cFFFF0000|Hspell:419144|h[Спотворювати]|h|r Серце Амірдрассілу!",
    ["|TInterface\\ICONS\\INV_Titan_Runestones_Icon.blp:32|t\r\n\r\nYou have translated the Crumbling Stele."] = "|TInterface\\ICONS\\INV_Titan_Runestones_Icon.blp:32|t\r\n\r\nТи перекла$p(в:ла) Зруйновану Стелу.",
    ["|TInterface\\ICONS\\Spell_Shadow_SoulLeech_2.blp:20|t A |cFFFF0000|Hspell:372851|h[Chillstorm]|h|r is forming around you!"] = "|TInterface\\ICONS\\Spell_Shadow_SoulLeech_2.blp:20|t Довкола тебе формується |cFFFF0000|Hspell:372851|h[Крижана буря]|h|r!",
    ["|TInterface\\ICONS\\UI_EmberCourt-Emoji-Elated.BLP:24|t You've received a |cFFFF0000|Hspell:1224863|h[Five Star Review!]|h|r"] = "|TInterface\\ICONS\\UI_EmberCourt-Emoji-Elated.BLP:24|t Ти отрима$p(в:ла) |cFFFF0000|Hspell:1224863|h[П'ятизірковий відгук!]|h|r",
    ["|TInterface\\ICONS\\inv_misc_bomb_05.blp:20|t The mine cart has been lit! Grab some dynamite before the cart takes off!"] = "|TInterface\\ICONS\\inv_misc_bomb_05.blp:20|t Запал вагонетки горить! Хапай динаміт, поки вагонетка не рушила!",
    ["|TInterface\\ICONS\\inv_misc_bomb_05.blp:20|t There is no mine cart at this location!"] = "|TInterface\\ICONS\\inv_misc_bomb_05.blp:20|t Тут немає вагонетки!",
    ["|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s begins casting |cFFFF0000|Hspell:259610|h[Bloody Apocalypse]|h|r! Take cover!"] = "|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s починає творити |cFFFF0000|Hspell:259610|h[Кривавий Апокаліпсис]|h|r! В укриття!",
